True def transform(grid):
    grid = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    line_colors = {grid[r][0] for r in range(height) if len(set(grid[r])) == 1}
    for color in line_colors:
        full_rows = [r for r in range(height) if all(value == color for value in grid[r])]
        full_columns = [c for c in range(width) if all(grid[r][c] == color for r in range(height))]
        for r in full_rows:
            grid[r] = [2] * width
        for c in full_columns:
            for r in range(height):
                grid[r][c] = 2
    return grid
